B.bQk=new A.d(["fenobarbital","claritromicina",B.q,"Claritromicina inibe CYP3A4, podendo aumentar os n\xedveis de fenobarbital. Fenobarbital induz CYP3A4, podendo reduzir claritromicina","Seda\xe7\xe3o excessiva por ac\xfamulo de fenobarbital. Poss\xedvel falha antibi\xf3tica por redu\xe7\xe3o de claritromicina","Monitorar seda\xe7\xe3o e n\xedvel de fenobarbital. Considerar azitromicina como alternativa (sem intera\xe7\xe3o CYP significativa com fenobarbital)","SEDA\xc7\xc3O AUMENTADA + EFIC\xc1CIA REDUZIDA \u2014 Monitorar seda\xe7\xe3o; preferir azitromicina",B.y,B.uW,B.t])
B.bRb=new A.d(["fenobarbital","eritromicina",B.q,"Eritromicina inibe CYP3A4, podendo aumentar os n\xedveis de fenobarbital. Fenobarbital induz CYP3A4, podendo reduzir eritromicina. Seda\xe7\xe3o aditiva por SNC","Seda\xe7\xe3o excessiva por ac\xfamulo de fenobarbital. Poss\xedvel falha antibi\xf3tica","Monitorar seda\xe7\xe3o. Preferir azitromicina. Se mantida: monitorar n\xedvel s\xe9rico de fenobarbital","SEDA\xc7\xc3O AUMENTADA \u2014 Monitorar seda\xe7\xe3o; preferir azitromicina a eritromicina",B.y,B.uW,B.t])
