B.axl=s(["Somnolencia","Astenia","Mareo","Cefalea","Irritabilidad/agitaci\xf3n","Depresi\xf3n","Psicosis (raro)","Infecci\xf3n VAS","Anorexia","Diplop\xeda"],t.s)
